					const words = countDocVisibleChars(reviewCandidate?.pmDoc ?? officialPmDoc);
					const reviewSummary = reviewCandidate ? renderedReviewSummary(officialPmDoc, reviewCandidate.renderModel) : null;
					const effectiveReview = Boolean(reviewSummary?.reviewingPatchIds.length);
					const wholeDocReview = reviewCandidate ? isWholeDocReview({ pmDoc: officialPmDoc }, reviewCandidate.renderModel, effectiveReview) : false;
					const reviewSuggestionIds = reviewSummary?.reviewingPatchIds ?? [];
