					const lengthStatus = lengthReport?.status ?? "not-requested";
					writeTurns.recordLengthResult(exec, bound.engineSessionId, words, lengthReport);
					const instructionLeakWarning = draftInstructionLeakWarning(renderedQingml, !args.docRef);
					const warnings = [...lostBlocks > 0 ? [`生成了 ${submittedBlocks} 项正文内容，文稿实际保留 ${outline.blocks} 项；有 ${lostBlocks} 项未通过格式检查。请重新查看文稿，补回缺失内容。`] : [], ...instructionLeakWarning ? [instructionLeakWarning] : []];
